@startuml

class Boeing {
  + Name : string
}

class Airline {
  + Name : string
  + ID : string
}

class Employee {
  + Name : string
  + ID : string
}

class Salesperson {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : float
  + Options : string
  + DeliveryDate : date
}

class Aircraft {
  + SerialNumber : string
  + ModelType : string
}

Boeing "1" -- "0..*" Contract : sells
Employee "1" -- "0..*" Salesperson : employs
Salesperson "1" -- "0..*" Contract : manages
Contract "1" *-- "1..*" Acquisition : consists of
Acquisition "1" -- "1" Aircraft : concerns
Airline "1" -- "0..*" Contract : signs
Airline "0..1" o-- "0..*" Airline : daughterOf
Salesperson --|> Employee

@enduml

